&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Pasar una enumeración como array ahora lanza una
     InvalidArgumentException.




    8.5.0

     Pasar un object como array está deprecado.

  &reftitle.examples;



    Ejemplo con ArrayObject::__construct


<?php

$array = [
    '1' => 'one',
    '2' => 'two',
    '3' => 'three'
];

$arrayobject = new ArrayObject($array);

var_dump($arrayobject);

?>


   &example.outputs;


object(ArrayObject)#1 (1) {
  ["storage":"ArrayObject":private]=>
  array(3) {
    [1]=>
    string(3) "one"
    [2]=>
    string(3) "two"
    [3]=>
    string(5) "three"
  }
}
